('camera-petkit-petwant',(SELECT id FROM categories WHERE slug='pet-cameras'),'petkit-petwant-camera','PETKIT PetWant Camera','PETKIT',79.99,'$79.99','Optional plan',3.6,'A simple wide-angle camera that pairs with PETKIT routines, with fewer advanced controls than dedicated security cameras.','PETKIT households wanting one companion app','https://images.unsplash.com/photo-1519052537078-e6302a4968d4?w=700&h=440&fit=crop&auto=format','products/petkit-petwant-camera.webp','PETKIT PetWant pet camera','PETKIT','https://petkit.com/','Sep 2026',8,FALSE,TRUE),
