('door-sureflap-dualscan',(SELECT id FROM categories WHERE slug='smart-pet-doors'),'sureflap-dualscan-connect','SureFlap DualScan Connect','SureFlap',249.99,'$249.99','Optional hub features',4.0,'A microchip door with inside-and-outside permissions for multi-cat homes, with a smaller opening than dog doors.','Multi-cat homes with selective access','https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=700&h=520&fit=crop&auto=format','products/sureflap-dualscan-connect.webp','SureFlap DualScan Connect microchip pet door','SureFlap','https://www.surepetcare.com/','Sep 2026',6,FALSE,TRUE),
('health-whistle-health',(SELECT id FROM categories WHERE slug='pet-health-monitors'),'whistle-health-monitor','Whistle Health Monitor','Whistle',119.95,'$119.95','$8.25/mo',3.7,'A collar-based wellness dashboard for activity, sleep, and scratching trends, with insights tied to a subscription.','Owners watching recurring wellness patterns','https://images.unsplash.com/photo-1583511655826-05700d52f4d9?w=700&h=520&fit=crop&auto=format','products/whistle-health-monitor.webp','Whistle Health pet monitor','Whistle','https://www.whistle.com/','Sep 2026',5,FALSE,TRUE),
('health-petivity-litter-monitor-2',(SELECT id FROM categories WHERE slug='pet-health-monitors'),'petivity-smart-litter-monitor-2','Petivity Smart Litter Box Monitor 2','Petivity',119.99,'$119.99','No required plan',3.8,'A scale-based monitor that tracks litter-box visits and weight trends without putting a collar on the pet.','Multi-cat homes tracking litter habits','https://images.unsplash.com/photo-1519052537078-e6302a4968d4?w=700&h=520&fit=crop&auto=format','products/petivity-smart-litter-monitor-2.webp','Petivity Smart Litter Box Monitor 2','Petivity','https://petivity.com/','Sep 2026',6,FALSE,TRUE)
