INSERT INTO guides
  (slug,category_id,category_label,title,description,read_time,updated_label,image_url,image_key,content_json,sort_order,is_published)
VALUES
('automatic-litter-box-maintenance-routine',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Litter Boxes','Build an automatic litter box maintenance routine','A simple weekly and monthly checklist keeps sensors, waste drawers, seals, and odor control working consistently.','6 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='automatic-litter-boxes'),'guides/automatic-litter-box-maintenance-routine.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Daily glance','body','Check the waste level, litter supply, and whether the cycle completed.'),JSON_OBJECT('title','Weekly clean','body','Wipe sensors and contact surfaces with the manufacturer-approved method.'),JSON_OBJECT('title','Monthly reset','body','Inspect seals, filters, and moving parts before buildup causes a jam.'))),16,TRUE),
('smart-feeder-backup-plan',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'Smart Pet Feeders','Create a backup plan for a smart feeder','Pair schedules with a backup meal, a power check, and a person who can verify dispensing when you are away.','5 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='smart-pet-feeders'),'guides/smart-feeder-backup-plan.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Test before travel','body','Run a manual portion and confirm the bowl is accessible.'),JSON_OBJECT('title','Keep a backup meal','body','Leave a measured backup portion for any missed schedule.'),JSON_OBJECT('title','Share access','body','Make sure a trusted person can check the feeder and pets.'))),17,TRUE),
('gps-tracker-coverage-checklist',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'GPS Pet Trackers','GPS tracker coverage and battery checklist','Understand cellular dead zones, live-mode battery cost, geofence timing, and what to do when a location is stale.','7 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='gps-pet-trackers'),'guides/gps-tracker-coverage-checklist.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Map your routine','body','Test the tracker around your home, usual walks, and likely roaming areas.'),JSON_OBJECT('title','Set realistic geofences','body','Allow enough room for GPS drift without making alerts meaningless.'),JSON_OBJECT('title','Plan for low battery','body','Charge on a repeatable schedule and keep a backup identification method.'))),18,TRUE),
('pet-camera-privacy-setup',(SELECT id FROM categories WHERE slug='pet-cameras'),'Pet Cameras','Pet camera privacy and placement setup','Use strong account security, thoughtful placement, and local-storage settings to monitor pets without overexposing your home.','6 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='pet-cameras'),'guides/pet-camera-privacy-setup.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Choose the view','body','Aim at pet areas and entrances rather than private rooms whenever possible.'),JSON_OBJECT('title','Lock the account','body','Use a unique password and two-factor authentication if available.'),JSON_OBJECT('title','Review storage','body','Know how long clips are retained and who can access shared feeds.'))),19,TRUE),
('water-fountain-cleaning-calendar',(SELECT id FROM categories WHERE slug='smart-water-fountains'),'Smart Water Fountains','Set a water fountain cleaning calendar','A repeatable cleaning cadence prevents biofilm, pump noise, and weak flow before pets stop drinking.','5 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='smart-water-fountains'),'guides/water-fountain-cleaning-calendar.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Refresh often','body','Top up with fresh water and remove visible hair or food daily.'),JSON_OBJECT('title','Deep clean','body','Disassemble the pump and drinking path on the maker\'s recommended cadence.'),JSON_OBJECT('title','Replace filters','body','Use the household\'s water hardness and pet count to set reminders.'))),20,TRUE),
('pet-door-installation-measurements',(SELECT id FROM categories WHERE slug='smart-pet-doors'),'Smart Pet Doors','Measure before installing a smart pet door','Get the flap height, pet clearance, wall thickness, and power route right before cutting or drilling.','6 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='smart-pet-doors'),'guides/pet-door-installation-measurements.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Measure the pet','body','Use shoulder height and the widest point of the pet, not a generic breed chart.'),JSON_OBJECT('title','Measure the opening','body','Check the clear flap dimensions and the surrounding trim or wall.'),JSON_OBJECT('title','Plan power','body','Keep outlets, hubs, and manual override access reachable after installation.'))),21,TRUE),
('pet-health-monitor-baseline',(SELECT id FROM categories WHERE slug='pet-health-monitors'),'Pet Health Monitors','How to establish a pet health baseline','Record normal activity, weight, sleep, and litter routines before using a monitor to spot meaningful changes.','7 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='pet-health-monitors'),'guides/pet-health-monitor-baseline.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Observe first','body','Write down appetite, mobility, sleep, and bathroom patterns for several days.'),JSON_OBJECT('title','Check device fit','body','A loose collar or shared litter box can make a trend unreliable.'),JSON_OBJECT('title','Escalate wisely','body','Use persistent changes as a prompt to contact a veterinarian, not as a diagnosis.'))),22,TRUE)
INSERT INTO troubleshooting_guides
  (slug,category_id,product_id,product_name,problem,title,description,difficulty,estimated_time,views_count,updated_label,content_json,sort_order,is_published)
VALUES
('pura-max-2-cycle-stops',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),(SELECT id FROM products WHERE slug='petkit-pura-max-2'),'PETKIT Pura Max 2','Cleaning cycle stops before completing','Pura Max 2 cycle stops','Check the drum position, waste drawer, sensor window, and litter level before restarting.','Moderate','20 min',0,'Sep 2026',JSON_OBJECT('safety','Keep pets away during a supervised test cycle.'),25,TRUE),
('petsafe-smart-feed-2-not-connecting',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),(SELECT id FROM products WHERE slug='petsafe-smart-feed-2'),'PetSafe Smart Feed 2.0','Feeder will not connect to the app','Smart Feed 2.0 not connecting','Confirm the supported Wi-Fi band, Bluetooth setup distance, and account pairing state.','Moderate','20 min',0,'Sep 2026',JSON_OBJECT('safety','Leave a backup meal while changing network settings.'),26,TRUE),
('fi-series-3-geofence-late',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),(SELECT id FROM products WHERE slug='fi-series-3-smart-collar'),'Fi Series 3 Smart Dog Collar','Escape alert arrives late','Fi Series 3 geofence alert late','Review geofence size, LTE coverage, collar battery, and the last successful location timestamp.','Moderate','20 min',0,'Sep 2026',JSON_OBJECT('safety','Do not wait for an alert before checking on a missing dog.'),27,TRUE),
('eufy-s350-video-blurry',(SELECT id FROM categories WHERE slug='pet-cameras'),(SELECT id FROM products WHERE slug='eufy-pet-camera-s350'),'eufy Pet Camera S350','Video looks soft or blurry','eufy S350 video blurry','Clean the lens, verify stream quality, and improve lighting before changing tracking settings.','Easy fix','10 min',0,'Sep 2026',JSON_OBJECT('safety','A camera view is not a substitute for an in-person safety check.'),28,TRUE),
('pioneer-raindrop-pump-noisy',(SELECT id FROM categories WHERE slug='smart-water-fountains'),(SELECT id FROM products WHERE slug='pioneer-raindrop-stainless'),'Pioneer Pet Raindrop Stainless','Pump is noisy or rattling','Raindrop fountain pump noisy','Refill to the correct level and clear hair or debris from the impeller and intake.','Easy fix','15 min',0,'Sep 2026',JSON_OBJECT('safety','Unplug the fountain before opening the pump.'),29,TRUE),
('sureflap-dualscan-not-reading',(SELECT id FROM categories WHERE slug='smart-pet-doors'),(SELECT id FROM products WHERE slug='sureflap-dualscan-connect'),'SureFlap DualScan Connect','Door does not recognize a registered microchip','DualScan not reading chip','Check battery, scanner alignment, registration, and whether the pet is moving through too quickly.','Moderate','20 min',0,'Sep 2026',JSON_OBJECT('safety','Keep manual access available while testing recognition.'),30,TRUE),
('petivity-monitor-weight-drift',(SELECT id FROM categories WHERE slug='pet-health-monitors'),(SELECT id FROM products WHERE slug='petivity-smart-litter-monitor-2'),'Petivity Smart Litter Box Monitor 2','Weight readings drift between visits','Petivity monitor weight drift','Place the scale on a hard level surface and confirm the same litter-box setup between readings.','Easy fix','15 min',0,'Sep 2026',JSON_OBJECT('safety','Treat unusual readings as a prompt for observation, not a diagnosis.'),31,TRUE)
INSERT INTO troubleshooting_steps (guide_id,instruction,sort_order)
