SET NAMES utf8mb4;

-- Round-two catalog expansion: two additional products per category.
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),name=VALUES(name),brand=VALUES(brand),price=VALUES(price),price_display=VALUES(price_display),subscription=VALUES(subscription),score=VALUES(score),verdict=VALUES(verdict),best_for=VALUES(best_for),image_url=VALUES(image_url),image_key=VALUES(image_key),alt_text=VALUES(alt_text),merchant_name=VALUES(merchant_name),merchant_url=VALUES(merchant_url),updated_label=VALUES(updated_label),rank_order=VALUES(rank_order),is_published=TRUE;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),product_a_id=VALUES(product_a_id),product_b_id=VALUES(product_b_id),product_a_name=VALUES(product_a_name),product_b_name=VALUES(product_b_name),verdict=VALUES(verdict),content_json=VALUES(content_json),updated_label=VALUES(updated_label),sort_order=VALUES(sort_order),is_published=TRUE;

SELECT x.id,v.pick_name,v.audience,v.sort_order FROM comparisons x JOIN (
SELECT 'petkit-pura-max-2-vs-catgenie-ai' slug,'PETKIT Pura Max 2' pick_name,'Owners wanting a premium globe without plumbing work.' audience,1 sort_order UNION ALL SELECT 'petkit-pura-max-2-vs-catgenie-ai','CatGenie A.I.','Utility rooms where self-washing and consumables are acceptable.',2 UNION ALL
SELECT 'wopet-7l-vs-petsafe-smart-feed-2','WOPET 7L Smart Feeder','Large pets and owners who refill less often.',1 UNION ALL SELECT 'wopet-7l-vs-petsafe-smart-feed-2','PetSafe Smart Feed 2.0','Owners prioritizing a polished schedule app.',2 UNION ALL
SELECT 'fi-series-3-vs-pawscout-smarter','Fi Series 3 Smart Dog Collar','Escape-prone dogs needing dependable LTE alerts.',1 UNION ALL SELECT 'fi-series-3-vs-pawscout-smarter','Pawscout Smarter GPS Tracker','Owners avoiding a required membership.',2 UNION ALL
SELECT 'eufy-s350-vs-petkit-petwant','eufy Pet Camera S350','Owners who want sharper video and local storage.',1 UNION ALL SELECT 'eufy-s350-vs-petkit-petwant','PETKIT PetWant Camera','PETKIT households wanting one companion app.',2 UNION ALL
SELECT 'pioneer-raindrop-vs-catit-flower-stainless','Pioneer Pet Raindrop Stainless','Cats that like a broad, quiet drinking surface.',1 UNION ALL SELECT 'pioneer-raindrop-vs-catit-flower-stainless','Catit Flower Fountain Stainless Top','Cats that respond to adjustable flow.',2 UNION ALL
SELECT 'petsafe-smartdoor-vs-sureflap-dualscan','PetSafe SmartDoor Connected Pet Door','Homes using schedules across several pets.',1 UNION ALL SELECT 'petsafe-smartdoor-vs-sureflap-dualscan','SureFlap DualScan Connect','Cat owners needing separate in/out permissions.',2 UNION ALL
SELECT 'whistle-health-vs-petivity-monitor-2','Whistle Health Monitor','Owners monitoring whole-day activity and sleep.',1 UNION ALL SELECT 'whistle-health-vs-petivity-monitor-2','Petivity Smart Litter Box Monitor 2','Multi-cat homes focused on litter and weight trends.',2
) v ON v.slug=x.slug WHERE NOT EXISTS (SELECT 1 FROM comparison_best_for b WHERE b.comparison_id=x.id AND b.pick_name=v.pick_name);

ON DUPLICATE KEY UPDATE title=VALUES(title),pick_product_id=VALUES(pick_product_id),pick_name=VALUES(pick_name),budget=VALUES(budget),tradeoff=VALUES(tradeoff),content_json=VALUES(content_json),sort_order=VALUES(sort_order),is_published=TRUE;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),category_label=VALUES(category_label),title=VALUES(title),description=VALUES(description),read_time=VALUES(read_time),updated_label=VALUES(updated_label),image_url=VALUES(image_url),image_key=VALUES(image_key),content_json=VALUES(content_json),sort_order=VALUES(sort_order),is_published=TRUE;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),product_id=VALUES(product_id),product_name=VALUES(product_name),problem=VALUES(problem),title=VALUES(title),description=VALUES(description),difficulty=VALUES(difficulty),estimated_time=VALUES(estimated_time),updated_label=VALUES(updated_label),content_json=VALUES(content_json),sort_order=VALUES(sort_order),is_published=TRUE;

SELECT g.id,v.instruction,v.sort_order FROM troubleshooting_guides g JOIN (
SELECT 'pura-max-2-cycle-stops' slug,'Confirm the drum and waste drawer are seated correctly.' instruction,1 sort_order UNION ALL SELECT 'pura-max-2-cycle-stops','Wipe the sensor window and remove excess litter.',2 UNION ALL SELECT 'pura-max-2-cycle-stops','Restart one supervised cycle.',3 UNION ALL
SELECT 'petsafe-smart-feed-2-not-connecting','Bring the feeder and phone close to the router.',1 UNION ALL SELECT 'petsafe-smart-feed-2-not-connecting','Confirm the network uses a supported 2.4 GHz setup.',2 UNION ALL SELECT 'petsafe-smart-feed-2-not-connecting','Re-run pairing only after noting the current schedule.',3 UNION ALL
SELECT 'fi-series-3-geofence-late','Check the collar battery and last location timestamp.',1 UNION ALL SELECT 'fi-series-3-geofence-late','Test the geofence in an open area with known LTE coverage.',2 UNION ALL SELECT 'fi-series-3-geofence-late','Widen the boundary slightly to account for GPS drift.',3 UNION ALL
SELECT 'eufy-s350-video-blurry','Clean the lens with a soft dry cloth.',1 UNION ALL SELECT 'eufy-s350-video-blurry','Set the stream to a higher quality when bandwidth allows.',2 UNION ALL SELECT 'eufy-s350-video-blurry','Add light or reposition away from a bright window.',3 UNION ALL
SELECT 'pioneer-raindrop-pump-noisy','Unplug the fountain and lift out the pump.',1 UNION ALL SELECT 'pioneer-raindrop-pump-noisy','Clear hair and debris from the intake and impeller.',2 UNION ALL SELECT 'pioneer-raindrop-pump-noisy','Refill to the marked level before testing.',3 UNION ALL
SELECT 'sureflap-dualscan-not-reading','Replace the batteries and wait for the scan light.',1 UNION ALL SELECT 'sureflap-dualscan-not-reading','Confirm the chip number is registered to the correct pet.',2 UNION ALL SELECT 'sureflap-dualscan-not-reading','Walk the pet through slowly and squarely.',3 UNION ALL
SELECT 'petivity-monitor-weight-drift','Move the monitor onto a hard, level floor.',1 UNION ALL SELECT 'petivity-monitor-weight-drift','Keep litter depth and box position consistent.',2 UNION ALL SELECT 'petivity-monitor-weight-drift','Compare several readings before acting on a trend.',3
) v ON v.slug=g.slug WHERE NOT EXISTS (SELECT 1 FROM troubleshooting_steps s WHERE s.guide_id=g.id AND s.instruction=v.instruction);
